async def run(model, connections, prompt: str) -> str:
    """Testcase adapter: one model-driven run over the real Activity tools.

    Returns ``"✓"`` or ``"✗ ..."`` per the onboarding cell contract. When no
    connection ids are configured the cell reports a legible skip instead of
    invoking tools that cannot resolve.
    """
    connections = connections or {}
    if not any(connections.values()):
        return "✗ no IS connections configured (model_spec.is_tools.connections)"
    graph = build_graph(model, connections)
    if hasattr(graph, "compile"):  # create_agent returns an uncompiled StateGraph
        graph = graph.compile()
    result = await graph.ainvoke(AgentInput(prompt=prompt))
    content = (result or {}).get("content") if isinstance(result, dict) else getattr(result, "content", None)
    if content and str(content).strip():
        return "✓"
    return "✗ empty response"
